def find_Max_Num(nums):
    # Convert all numbers to strings, sort them in a custom order to form the largest number
    # Then join and convert back to integer
    from functools import cmp_to_key

    def compare(x, y):
        if x + y > y + x:
            return -1
        elif x + y < y + x:
            return 1
        else:
            return 0

    str_nums = [str(num) for num in nums]
    str_nums.sort(key=cmp_to_key(compare))

    result = int(''.join(str_nums))
    return result

def find_Max_Num(lst):
    # Convert all numbers to strings
    str_nums = [str(num) for num in lst]

    # Custom comparison: a+b > b+a means 'a' should come before 'b'
    # We need to sort in descending order based on this custom logic
    from functools import cmp_to_key

    def compare(a, b):
        if a + b > b + a:
            return -1  # a comes before b (descending)
        elif a + b < b + a:
            return 1   # b comes before a (descending)
        else:
            return 0

    # Sort using the custom comparator
    str_nums.sort(key=cmp_to_key(compare))

    # Concatenate and convert to integer
    result = int(''.join(str_nums))

    return result

# Test case
assert find_Max_Num([1,2,3]) == 321

