def dif_Square(n):
    if n <= 0:
        return False
    # A number can be represented as difference of two squares if it is odd or divisible by 4
    # i.e., not of the form 4k + 2
    return n % 4 != 2

def is_samepatterns(patterns, words):
    if len(patterns) != len(words):
        return False

    pattern_to_word = {}
    word_to_pattern = {}

    for p, w in zip(patterns, words):
        if p in pattern_to_word:
            if pattern_to_word[p] != w:
                return False
        else:
            pattern_to_word[p] = w

        if w in word_to_pattern:
            if word_to_pattern[w] != p:
                return False
        else:
            word_to_pattern[w] = p

    return True

