def magic_square_test(matrix):
    n = len(matrix)
    if n == 0:
        return False

    # Check if it's a square matrix
    for row in matrix:
        if len(row) != n:
            return False

    # Calculate the magic constant (sum of first row)
    magic_sum = sum(matrix[0])

    # Check rows
    for row in matrix:
        if sum(row) != magic_sum:
            return False

    # Check columns
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != magic_sum:
            return False

    # Check main diagonal
    diag1_sum = sum(matrix[i][i] for i in range(n))
    if diag1_sum != magic_sum:
        return False

    # Check anti-diagonal
    diag2_sum = sum(matrix[i][n - 1 - i] for i in range(n))
    if diag2_sum != magic_sum:
        return False

    return True

