def count_char_position(s: str) -> int:
    count = 0
    for index, char in enumerate(s):
        if char.isalpha():
            # Calculate the alphabetical position (a=1, b=2, ..., z=26)
            alpha_pos = ord(char.lower()) - ord('a') + 1
            # Check if the character's zero-based index matches its alphabetical position minus 1
            # Since zero-based index of 'a' is 0, and its alpha pos is 1, we check if index == alpha_pos - 1
            if index == alpha_pos - 1:
                count += 1
    return count

