def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Create two arrays: inc[i] stores the maximum sum of an increasing subsequence ending at i
    # and dec[i] stores the maximum sum of a decreasing subsequence starting at i

    inc = [0] * n
    dec = [0] * n

    # Initialize both arrays with the element itself
    for i in range(n):
        inc[i] = arr[i]
        dec[i] = arr[i]

    # Compute inc[i]: max sum of increasing subsequence ending at index i
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Compute dec[i]: max sum of decreasing subsequence starting at index i
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # The maximum bitonic sum is the maximum of inc[i] + dec[i] - arr[i] for all i
    # (subtracting arr[i] because it's counted twice)
    max_bitonic_sum = 0
    for i in range(n):
        current_sum = inc[i] + dec[i] - arr[i]
        if current_sum > max_bitonic_sum:
            max_bitonic_sum = current_sum

    return max_bitonic_sum

