    for i in range(n):
        msis[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and msis[j] + arr[i] > msis[i]:
                msis[i] = msis[j] + arr[i]

    # Compute msds
    for i in range(n - 1, -1, -1):
        msds[i] = arr[i]
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i] and msds[j] + arr[i] > msds[i]:
                msds[i] = msds[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum_val = 0
    for i in range(n):
        # The bitonic subsequence peaks at i, so we add msis[i] + msds[i] - arr[i]
        current_sum = msis[i] + msds[i] - arr[i]
        if current_sum > max_sum_val:
            max_sum_val = current_sum

