def max_aggregate(tuples_list):
    from collections import defaultdict

    aggregates = defaultdict(int)
    for name, value in tuples_list:
        aggregates[name] += value

    max_name = None
    max_value = -1

    for name, value in aggregates.items():
        if value > max_value:
            max_value = value
            max_name = name

    return (max_name, max_value)

