def get_max_sum(n, memo=None):
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n == 0:
        return 0

    max_val = n
    for divisor in [2, 3, 4, 5]:
        if n >= divisor:
            max_val = max(max_val, get_max_sum(n // divisor, memo) + get_max_sum(n % divisor, memo))

    memo[n] = max_val
    return max_val

