def max_Product(arr):
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements")

    # Sort the array to easily find the largest and smallest numbers
    sorted_arr = sorted(arr)

    # The highest product can be from either:
    # 1. The two largest numbers (last two in sorted array)
    # 2. The two smallest numbers (first two in sorted array, could be negative)

    n = len(sorted_arr)
    product1 = sorted_arr[n-1] * sorted_arr[n-2]
    product2 = sorted_arr[0] * sorted_arr[1]

    if product1 >= product2:
        return (sorted_arr[n-1], sorted_arr[n-2])
    else:
        return (sorted_arr[0], sorted_arr[1])

