def cal_sum(n):
    if n <= 0:
        return 0

    # Perrin sequence: P(0)=3, P(1)=0, P(2)=2, and P(n) = P(n-2) + P(n-3) for n > 2
    perrin = [3, 0, 2]

    # Generate Perrin numbers up to index n-1 (since we want sum of first n numbers)
    for i in range(3, n):
        next_val = perrin[i-2] + perrin[i-3]
        perrin.append(next_val)

    return sum(perrin[:n])

