def max_product(arr):
    if not arr:
        return 0

    n = len(arr)
    # dp[i] will store the maximum product of an increasing subsequence ending at index i
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                # If we extend the subsequence ending at j with arr[i]
                new_product = dp[j] * arr[i]
                if new_product > dp[i]:
                    dp[i] = new_product
        # Also consider just starting a new subsequence with arr[i] itself
        if arr[i] > dp[i]:
            dp[i] = arr[i]

    return max(dp)

