def text_match_wordz_middle(text):
    words = text.split()
    for word in words:
        # Extract only alphabetic characters from the word
        alpha_chars = [c for c in word if c.isalpha()]
        if len(alpha_chars) < 3:
            continue
        # Check if 'z' is strictly between the first and last alphabetic characters
        if alpha_chars[0] != 'z' and alpha_chars[-1] != 'z' and 'z' in alpha_chars[1:-1]:
            return True
    return False

