def is_decimal(s):
    try:
        num = float(s)
        # Check if it's a valid decimal number and has exactly 2 decimal places
        parts = s.split('.')
        if len(parts) != 2:
            return False
        integer_part, decimal_part = parts
        if not integer_part.isdigit() and not (integer_part.startswith('-') and integer_part[1:].isdigit()):
            return False
        if not decimal_part.isdigit():
            return False
        if len(decimal_part) != 2:
            return False
        return True
    except ValueError:
        return False

